# Generated by Descant: acceptance tests.

# frozen_string_literal: true

require "rails_helper"

RSpec.describe Timekeeping::ReservationRules do
  # "Keep the rows in the same order: not in company → not_found; provisional → provisional_elsewhere; committed by the same invoice → keep; committed active elsewhere → on_another_invoice; otherwise add_provisional."
  it "gives the same prepare outcome as before for each set of entry facts" do
    active_elsewhere = { invoice_id: 20, disposition: "active" }
    retained_elsewhere = { invoice_id: 20, disposition: "retained" }
    same_invoice = { invoice_id: 10, disposition: "active" }
    provisional = { invoice_id: 30 }
    cases = {
      { in_company: false, committed: nil, provisional:, invoice_id: 10 } => :not_found,
      { in_company: false, committed: active_elsewhere, provisional: nil, invoice_id: 10 } => :not_found,
      { in_company: true, committed: nil, provisional:, invoice_id: 10 } => :provisional_elsewhere,
      { in_company: true, committed: same_invoice, provisional: nil, invoice_id: 10 } => :keep,
      { in_company: true, committed: active_elsewhere, provisional: nil, invoice_id: 10 } => :on_another_invoice,
      { in_company: true, committed: retained_elsewhere, provisional: nil, invoice_id: 10 } => :add_provisional,
      { in_company: true, committed: nil, provisional: nil, invoice_id: 10 } => :add_provisional
    }

    expect(cases.keys.map { |entry| described_class.prepare_outcome(entry) }).to eq(cases.values)
    expect(described_class::PREPARE_TABLE).to be_frozen
    expect(described_class::PREPARE_TABLE).to all(be_frozen)
  end

  # The not-in-company row comes first, so the answer for another company's
  # entry never says whether or where that entry is reserved.
  it "answers not_found for an entry outside the company even when it is reserved elsewhere" do
    provisional = { invoice_id: 77, disposition: "active" }
    committed_active = { invoice_id: 77, disposition: "active" }
    committed_same_invoice = { invoice_id: 10, disposition: "active" }

    outcomes = [
      { in_company: false, committed: nil, provisional:, invoice_id: 10 },
      { in_company: false, committed: committed_active, provisional: nil, invoice_id: 10 },
      { in_company: false, committed: committed_same_invoice, provisional: nil, invoice_id: 10 },
      { in_company: false, committed: committed_active, provisional:, invoice_id: 10 },
      { in_company: false, committed: nil, provisional: nil, invoice_id: 10 }
    ].map { |entry| described_class.prepare_outcome(entry) }

    expect(outcomes).to eq([:not_found] * 5)
    expect(described_class.refusal?(:not_found)).to be(true)
    expect(described_class.refusal?(:keep)).to be(false)
  end

  it "refuses exactly the conflict reasons the reservations contract lists" do
    contract = YAML.safe_load_file(Rails.root.join("contracts/timekeeping/reservations.yml"))
    outcomes = %i[not_found provisional_elsewhere keep on_another_invoice add_provisional]

    refused = outcomes.select { |outcome| described_class.refusal?(outcome) }

    expect(refused).to match_array(%i[not_found provisional_elsewhere on_another_invoice])
    expect(refused.map(&:to_s)).to match_array(contract.fetch("conflict_reasons"))
    expect(TimekeepingContract::ReservationRules).to equal(described_class)
  end

  # "The existing contract mutation spec under `spec/contracts/timekeeping` must still fail when a
  # table row changes." A changed row must reach the answer through the table argument, and the
  # shared frozen table must keep answering as before.
  it "answers from a changed table copy without altering the shared table" do
    entry = { in_company: true, committed: { invoice_id: 7, disposition: "active" }, provisional: nil, invoice_id: 8 }
    changed = described_class::PREPARE_TABLE.map do |condition, outcome|
      [condition, outcome == :on_another_invoice ? :add_provisional : outcome]
    end

    expect(described_class.prepare_outcome(entry, table: changed)).to eq(:add_provisional)
    expect(described_class.prepare_outcome(entry)).to eq(:on_another_invoice)
    expect(described_class::PREPARE_TABLE.map(&:last))
      .to eq(%i[not_found provisional_elsewhere keep on_another_invoice add_provisional])
    expect(TimekeepingContract::ReservationRules::PREPARE_TABLE).to equal(described_class::PREPARE_TABLE)
  end
end
